#!/bin/bash

# Let me verify by checking individual sizes
echo "=== Files and their sizes ==="
find test_directory -mindepth 1 -type f -exec stat -c '%n: %s' {} \;

echo ""
echo "=== Directories and their sizes ==="
find test_directory -mindepth 1 -type d -exec stat -c '%n: %s' {} \;

echo ""
echo "=== Using du to check total ==="
du -sb test_directory
